import{_ as i,o as t,c as s,ak as a}from"./chunks/framework.Dpc0wyhY.js";const u=JSON.parse('{"title":"Automation Recipes","description":"","frontmatter":{},"headers":[],"relativePath":"guides/automation-recipes.md","filePath":"guides/automation-recipes.md"}'),o={name:"guides/automation-recipes.md"};function n(r,e,l,d,h,c){return t(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="automation-recipes" tabindex="-1">Automation Recipes <a class="header-anchor" href="#automation-recipes" aria-label="Permalink to “Automation Recipes”">​</a></h1><p>Flow and operation patterns for real automation: numbering schemes, event gates, webhooks, and raw SQL. For trigger and operation basics, see the <a href="/automation/">Automation</a> section.</p><h2 id="event-trigger-options" tabindex="-1">Event Trigger Options <a class="header-anchor" href="#event-trigger-options" aria-label="Permalink to “Event Trigger Options”">​</a></h2><p>An event hook flow&#39;s <code>options</code> object has two separate lists — putting collection names in <code>scope</code> makes the flow <strong>never fire, silently</strong>:</p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;action&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;scope&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;items.create&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;collections&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;app_orders&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;app_invoices&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;async&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>scope</code> holds event names; <code>collections</code> holds collection names. Because <code>{{$trigger.collection}}</code> interpolates the firing collection&#39;s name, one dynamic flow can serve many collections.</p><h2 id="trigger-shape" tabindex="-1"><code>$trigger</code> Shape <a class="header-anchor" href="#trigger-shape" aria-label="Permalink to “$trigger Shape”">​</a></h2><p>For <code>items.update</code> events the trigger payload is:</p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;payload&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;...changed fields...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;keys&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;id&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;collection&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;event&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;items.update&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p><code>payload</code> is <strong>not</strong> double-nested — <code>{{$trigger.payload.status}}</code>, not <code>{{$trigger.payload.payload.status}}</code>.</p><h2 id="gate-logic-inside-run-script-not-conditions" tabindex="-1">Gate Logic Inside Run Script, Not Conditions <a class="header-anchor" href="#gate-logic-inside-run-script-not-conditions" aria-label="Permalink to “Gate Logic Inside Run Script, Not Conditions”">​</a></h2><p>The Condition operation can silently misbehave; the reliable gate is a Run Script operation that <code>throw</code>s. A thrown error routes to the operation&#39;s <code>reject</code> path — leave it <code>null</code> and the chain stops cleanly.</p><h2 id="resolve-reject-targets-are-unique" tabindex="-1">Resolve/Reject Targets Are Unique <a class="header-anchor" href="#resolve-reject-targets-are-unique" aria-label="Permalink to “Resolve/Reject Targets Are Unique”">​</a></h2><p>Two operations cannot resolve to the same target, and an operation&#39;s existing <code>resolve</code> link must be cleared before it can point somewhere new. When inserting an operation into a chain, unlink the previous <code>resolve</code> first.</p><h2 id="prevent-self-trigger-loops" tabindex="-1">Prevent Self-Trigger Loops <a class="header-anchor" href="#prevent-self-trigger-loops" aria-label="Permalink to “Prevent Self-Trigger Loops”">​</a></h2><p>Any operation that writes back to the same collection that triggered the flow must set <code>emitEvents: false</code>. Without it the write re-fires the event and loops.</p><h2 id="the-key-field-on-update-operations" tabindex="-1">The <code>key</code> Field on Update Operations <a class="header-anchor" href="#the-key-field-on-update-operations" aria-label="Permalink to “The key Field on Update Operations”">​</a></h2><p>On item-update operations, <code>key</code> accepts a literal id or a template — <code>{{$last.key}}</code> and <code>{{$trigger.keys[0]}}</code> both resolve.</p><h2 id="serial-numbering" tabindex="-1">Serial Numbering <a class="header-anchor" href="#serial-numbering" aria-label="Permalink to “Serial Numbering”">​</a></h2><p>The standard <code>PREFIX-YYYY-NNNN</code> recipe, per-collection or per-tenant:</p><ol><li>Event trigger: <code>items.create</code> on the collection, <code>type: &quot;action&quot;</code>, <code>async: true</code>.</li><li>SQL Query operation (<code>sql_1</code>): compute the next number — select the max serial for the prefix+year and increment (or a counter table / sequence).</li><li>Update Data operation: write <code>{{sql_1.rows.0.serial}}</code> back to <code>{{$trigger.keys[0]}}</code>, with <code>emitEvents: false</code>.</li></ol><p>Creating records through raw SQL (for example from a <a href="/guides/public-endpoints.html">public endpoint</a>) does <strong>not</strong> emit <code>items.create</code>, so serial flows are bypassed — compute the serial inside the INSERT itself, typically in a CTE, to avoid double-stamping.</p><h2 id="webhook-triggers" tabindex="-1">Webhook Triggers <a class="header-anchor" href="#webhook-triggers" aria-label="Permalink to “Webhook Triggers”">​</a></h2><p>Webhook-triggered flows are invoked with <strong>GET</strong> <code>/flows/trigger/{id}</code> — a POST returns <code>403</code> unless the flow&#39;s <code>options.method</code> is set to <code>&quot;POST&quot;</code>. The response body is whatever the flow&#39;s last operation returns. Set <code>options.error_on_reject: true</code> on chart/API flows so failures surface instead of rendering empty.</p><h2 id="the-sql-query-operation" tabindex="-1">The SQL Query Operation <a class="header-anchor" href="#the-sql-query-operation" aria-label="Permalink to “The SQL Query Operation”">​</a></h2><p><code>likha_sql</code> is a <strong>custom operation</strong> shipped with the platform — it appears in the flow editor alongside the built-in operations and is enumerable via <code>GET /extensions?limit=-1</code>. It runs raw SQL server-side — multi-statement is fine — and is the sanctioned way to change things the REST layer cannot: relation internals such as <code>junction_field</code> and <code>one_deselect_action</code>, foreign-key cascade rules, and bulk fixes.</p><p>Options: <code>{ &quot;sql&quot;: &quot;...&quot;, &quot;binding&quot;: [] }</code>. It returns:</p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;sql&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;binding&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [], </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;rows&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [ { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;col&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;value&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } ] }</span></span></code></pre></div><ul><li>In downstream <strong>Update Data</strong> payloads, reference rows as <code>{{sql_1.rows.0.col}}</code>.</li><li>In <strong>Run Script</strong> operations, unwrap defensively: <code>const rows = data.sql_1.rows || data.sql_1</code>.</li><li><code>UPDATE</code>/<code>DELETE</code> statements return <code>rows: []</code> — there is no <code>RETURNING</code> unless you add one.</li><li>Writing <code>{{sql_1.0.x}}</code> (without <code>.rows</code>) stores the literal string <code>&quot;undefined&quot;</code>.</li><li>Interpolated values are <strong>not</strong> escaped — when building SQL from request input, run a validation Run Script first that strips or escapes quotes (<code>String(s).replace(/&#39;/g, &quot;&#39;&#39;&quot;)</code>).</li></ul><p>Run it from a webhook-triggered flow — the <code>manual</code> trigger is rejected over the API. After direct database changes, clear the system cache: <code>POST /utils/cache/clear</code> with <code>{&quot;cache&quot;:&quot;system&quot;}</code>.</p><h2 id="shell-expansion-corrupts-flow-options" tabindex="-1">Shell <code>$</code> Expansion Corrupts Flow Options <a class="header-anchor" href="#shell-expansion-corrupts-flow-options" aria-label="Permalink to “Shell $ Expansion Corrupts Flow Options”">​</a></h2><p><code>python -c &quot;... $trigger ...&quot;</code> or <code>curl --data &quot;... $last ...&quot;</code> inside double quotes silently strips <code>$trigger</code>, <code>$last</code>, and <code>$full</code>, storing mutilated options (<code>data. || {}</code>, <code>{{.key}}</code>) — the flow then dies silently. Always create or patch operations containing <code>$</code> tokens <strong>from a script file</strong>, never an inline command, and verify the stored options afterward.</p><h2 id="script-output-must-be-json-safe" tabindex="-1">Script Output Must Be JSON-Safe <a class="header-anchor" href="#script-output-must-be-json-safe" aria-label="Permalink to “Script Output Must Be JSON-Safe”">​</a></h2><p>A Run Script operation&#39;s return value must clone cleanly — <strong>no functions</strong>. An ECharts option containing <code>formatter: function(...)</code>, for example, fails with <code>could not be cloned</code>. Use string templates (<code>&quot;{b}: {c}&quot;</code>) instead of formatter functions.</p><h2 id="email-operations-need-smtp" tabindex="-1">Email Operations Need SMTP <a class="header-anchor" href="#email-operations-need-smtp" aria-label="Permalink to “Email Operations Need SMTP”">​</a></h2><p>The Send Email operation only works when <code>EMAIL_*</code> environment variables are configured on the server; otherwise the flow appears to succeed while sending nothing.</p>`,36)])])}const k=i(o,[["render",n]]);export{u as __pageData,k as default};
